def fizzbuzz(n):
    """
    Return the FizzBuzz string for a given number n.
    - Multiples of 3: "Fizz"
    - Multiples of 5: "Buzz"
    - Multiples of both 3 and 5: "FizzBuzz"
    - Otherwise: the number as a string
    """
    if n % 3 == 0 and n % 5 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)


def fizzbuzz_sequence(n):
    """Return a list of FizzBuzz strings for numbers 1 to n."""
    return [fizzbuzz(i) for i in range(1, n + 1)]


